import{_ as r,o as t,c as n,j as a,a as e,aa as s}from"./chunks/framework.BAs_AphD.js";const p="/buildary-help-preview/academy/img/provedene-prace/03.webp",i="/buildary-help-preview/media/cs/diary/dennizaznamyprac3.png",l="/buildary-help-preview/media/cs/diary/dennizaznamyprace5.png",d="/buildary-help-preview/academy/img/provedene-prace/06.webp",v="/buildary-help-preview/media/cs/diary/zmenaporadizaznamu.png",b=JSON.parse('{"title":"Provedené práce","description":"","frontmatter":{"title":"Provedené práce","wiki":"cs:diary:dailyentriesworks"},"headers":[],"relativePath":"diary/dailyentriesworks.md","filePath":"diary/dailyentriesworks.md","lastUpdated":1794209661000}'),z={name:"diary/dailyentriesworks.md"};function u(m,o,c,k,y,h){return t(),n("div",null,[...o[0]||(o[0]=[a("h1",{id:"provedene-prace",tabindex:"-1"},[e("Provedené práce "),a("a",{class:"header-anchor",href:"#provedene-prace","aria-label":'Permalink to "Provedené práce"'},"​")],-1),a("p",null,[e("Sekce "),a("strong",null,"Provedené práce"),e(" popisuje, co se ten den na stavbě udělalo. Ke každé práci můžete doplnit dodavatele a množství, přiložit fotografie, vybrat položku z rozpočtu a označit místo v mapě nebo ve výkresu.")],-1),a("p",null,[e("Krok za krokem: "),a("a",{href:"/buildary-help-preview/akademie/provedene-prace"},"Zapsat provedené práce"),e(" v Akademii.")],-1),a("div",{class:"video"},[a("iframe",{src:"https://www.youtube-nocookie.com/embed/cqFztSwwmos",title:"Video: Provedené práce",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),s('<h2 id="zapsat-praci" tabindex="-1">Zapsat práci <a class="header-anchor" href="#zapsat-praci" aria-label="Permalink to &quot;Zapsat práci&quot;">​</a></h2><p>V sekci klikněte na <strong>Přidat záznam</strong>. Otevře se okno <strong>Provedené práce</strong>.</p><figure class="shot" style="--w:760px;"><img src="'+p+'" alt="Okno Provedené práce s polem Popis, dodavatelem, množstvím a přílohami" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Pole</th><th>Co do něj patří</th></tr></thead><tbody><tr><td><strong>Popis</strong></td><td>Popis provedené práce, libovolně dlouhý. Text můžete nadiktovat tlačítkem <strong>Nadiktovat</strong>.</td></tr><tr><td><strong>Název dodavatele</strong></td><td>Kdo práci provedl.</td></tr><tr><td><strong>Množství</strong> a <strong>Měrná jednotka</strong></td><td>Kolik se udělalo.</td></tr><tr><td><strong>Přílohy k záznamu</strong></td><td>Fotografie a dokumenty – viz <a href="#prilohy">Přílohy</a>.</td></tr></tbody></table><p>Která další pole okno nabídne (například <strong>Popis položky</strong>, <strong>Poloha</strong> nebo <strong>Výkres</strong>) a která jsou povinná, určuje <a href="/buildary-help-preview/diary/diarysettings">Nastavení deníku</a> na záložce <strong>Provedené práce</strong>.</p><p><strong>Uložit a nový</strong> záznam uloží a formulář vyčistí pro další práci. <strong>Uložit</strong> záznam uloží a okno zavře.</p><h3 id="popis-z-fotografii" tabindex="-1">Popis z fotografií <a class="header-anchor" href="#popis-z-fotografii" aria-label="Permalink to &quot;Popis z fotografií&quot;">​</a></h3><p>Tlačítko <strong>Generovat pomocí AI</strong> v horní části okna vytvoří návrh popisu z fotografií ze stavby. Návrh před uložením zkontrolujte a upravte.</p><h2 id="prace-z-rozpoctu" tabindex="-1">Práce z rozpočtu <a class="header-anchor" href="#prace-z-rozpoctu" aria-label="Permalink to &quot;Práce z rozpočtu&quot;">​</a></h2><p>Pokud je na stavbě zapnutý modul <a href="/buildary-help-preview/performedworks/">Soupisy provedených prací</a> a je v něm načtený rozpočet, můžete práci vybrat z položek rozpočtu. V Nastavení deníku musí být zobrazené pole <strong>Popis položky</strong> a v poli <strong>Filtrace položek rozpočtu</strong> vybraná stavba nebo její část – viz <a href="/buildary-help-preview/diary/diarysettings#provedene-prace">Nastavení deníku</a>.</p><p>Začněte do pole <strong>Popis položky</strong> psát a vyberte položku z nabídky. Text vybrané položky můžete v záznamu upravit – vazba na původní položku rozpočtu zůstane zachovaná.</p><figure class="shot" style="--w:560px;"><img src="'+i+'" alt="Výběr položky rozpočtu v poli Popis položky" loading="lazy"></figure><p>Tlačítko <strong>Kontrola prací</strong> v záhlaví sekce porovná zapsané práce s rozpočtem.</p><h2 id="misto-prace-v-mape-a-ve-vykresu" tabindex="-1">Místo práce v mapě a ve výkresu <a class="header-anchor" href="#misto-prace-v-mape-a-ve-vykresu" aria-label="Permalink to &quot;Místo práce v mapě a ve výkresu&quot;">​</a></h2><p>Zejména u liniových staveb se hodí určit, kde se práce prováděla:</p><ul><li><strong>V mapě</strong> – v Nastavení deníku zapněte pole <strong>Poloha</strong>. U záznamu pak zadáte místo GPS souřadnicemi v mapě.</li><li><strong>Ve výkresu</strong> – v Nastavení deníku zapněte pole <strong>Výkres</strong> a v Nastavení stavby nahrajte alespoň jeden výkres (viz <a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a>). V záznamu vyberete část stavby a výkres a tlačítkem <strong>Zadej značky</strong> označíte místa ve výkresu.</li></ul><figure class="shot" style="--w:560px;"><img src="'+l+'" alt="Část stavby a umístění značek ve výkresu v okně Provedené práce" loading="lazy"></figure><p>Záznam navázaný na výkres poznáte podle ikony <strong>Výkres</strong>, záznam navázaný na mapu podle ikony <strong>Umístění</strong>.</p><h2 id="prilohy" tabindex="-1">Přílohy <a class="header-anchor" href="#prilohy" aria-label="Permalink to &quot;Přílohy&quot;">​</a></h2><p>Přílohy přidáte přetažením souborů do pole <strong>Přílohy k záznamu</strong>, nebo tlačítkem <strong>Nahrát přílohu</strong>.</p><ul><li>Jeden soubor může mít nejvýše 30 MB, k jednomu záznamu lze přiložit až 20 souborů.</li><li>Formát souborů aplikace neomezuje. Administrátor domény ale může vybrané typy souborů na doméně zakázat.</li><li>Velikost a počet příloh přizpůsobte připojení k internetu. Velké přílohy zpomalí stahování a nahrávání podepsaného Denního protokolu.</li></ul><div class="warning custom-block"><p class="custom-block-title">Komprimované soubory</p><p>Nevkládejte do příloh archivy ZIP, RAR a podobné. Přílohy jsou součástí PDF Denního protokolu a většina bezplatných prohlížečů PDF neumí archivy z PDF uložit.</p></div><h2 id="uprava-poradi-a-ukoly" tabindex="-1">Úprava, pořadí a úkoly <a class="header-anchor" href="#uprava-poradi-a-ukoly" aria-label="Permalink to &quot;Úprava, pořadí a úkoly&quot;">​</a></h2><p>V záhlaví každého záznamu jsou tlačítka <strong>Upravit záznam</strong>, <strong>Vytvoř nový úkol pro tento záznam</strong> a <strong>Smazat</strong>. Upravit a smazat můžete jen své záznamy a jen do uzamčení dne. Jak k záznamu založit úkol, popisují <a href="/buildary-help-preview/diary/dailyentriesothers#ukol-k-zaznamu">Další záznamy</a>.</p><figure class="shot" style="--w:760px;"><img src="'+d+'" alt="Zapsaná práce v sekci Provedené práce s tlačítky Upravit záznam, Vytvoř nový úkol pro tento záznam a Smazat" loading="lazy"></figure><p>Pořadí záznamů změníte přetažením záznamu na jiné místo. Stejně se mění pořadí v sekci Další záznamy, kde ho lze v <a href="/buildary-help-preview/diary/diarysettings#dalsi-zaznamy">Nastavení deníku</a> zakázat volbou <strong>Zakázat změny pořadí záznamů</strong>.</p><figure class="shot" style="--w:600px;"><img src="'+v+'" alt="Přetažení záznamu na jinou pozici v sekci" loading="lazy"></figure><p>Práce z jiného dne převezmete tlačítkem <strong>Kopírovat záznamy</strong>, práce z deníků částí stavby volbou <strong>Kopíruj z deníků částí staveb</strong> – viz <a href="/buildary-help-preview/diary/copydailyentries">Kopírovat záznamy</a>.</p>',28)])])}const P=r(z,[["render",u]]);export{b as __pageData,P as default};
